---@field controller                    	Engine.UI.UILuaDialog                   
---@field BtnClose                      	UnityEngine.RectTransform               
---@field RankingLoopView               	SuperScrollView.LoopListView2
local OverseaManageCafeCattyRankRewardDialog = Class("OverseaManageCafeCattyRankRewardDialog")

function OverseaManageCafeCattyRankRewardDialog:__init()
    self.rankType = MaidCoffeeConstants.CoffeeRankType.CafeTipRank
    self._rankRewards = nil
end

function OverseaManageCafeCattyRankRewardDialog:__delete()
    self._rankRewards = nil
end

function OverseaManageCafeCattyRankRewardDialog:Awake()
    SetButtonAction(self.BtnClose, function()
        UIModule.CloseDialog(self.controller)
    end)
    local emptyCloset = self.controller.transform:Find("EmptyClose")
    if emptyCloset then
        SetButtonAction(emptyCloset, function()
            UIModule.CloseDialog(self.controller)
        end)
    end
end

function OverseaManageCafeCattyRankRewardDialog:InitRankReward()
    if self.rankType == MaidCoffeeConstants.CoffeeRankType.CafeTipRank then
        self._rankRewards = CfUtils.GetCf(AutoIds.IdSetting4041, "MaidCoffeeCattyRankVo", true)
    elseif self.rankType == MaidCoffeeConstants.CoffeeRankType.VipOrderRank then
        self._rankRewards = CfUtils.GetCf(AutoIds.IdSetting3057, "MaidCoffeeCattyRankVo", true)
    end
end

function OverseaManageCafeCattyRankRewardDialog:RefreshRankReward()
    if self.RankingLoopView then
        if not self.RankingLoopView.IsListViewInit then
            self.RankingLoopView:InitListView(#self._rankRewards, Bind(self, self.OnGetRankCellByIndex))
        else
            GameUtils.ReloadData(self.RankingLoopView, #self._rankRewards)
        end
    end
end

function OverseaManageCafeCattyRankRewardDialog:OnGetRankCellByIndex(listView, index)
    if index < 0 then
        return nil
    end

    local data = self._rankRewards[index + 1]
    local cell = listView:NewListViewItem("Cell")
    local scr = CfUtils.GetLuaScr(cell.gameObject, UIRankRewardCell)
    if scr then
        scr:RefreshRankReward(data, index)
        scr:PlayAni("Go")
    end

    return cell
end

function OverseaManageCafeCattyRankRewardDialog:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        xTry(function()
            self:RefreshRankReward()
        end)
    end))
    return coWait
end

function OverseaManageCafeCattyRankRewardDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        xTry(function()
            ---@type table
            local argument = self.controller.Argument.parameters
            if argument and argument.type then
                self.rankType = checkNumber(argument.type)
            end
            self:InitRankReward()
        end)
    end))
    return coWait
end

function OverseaManageCafeCattyRankRewardDialog:OnFinalize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        xTry(function()
            self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
            self:Delete()
            self = nil --lua层的gc需要
        end)
    end))
